def IsJointlyInvariant {X} m s (L : X → (WeylIndex (n m) κ → ℂ) →ₗ[ℂ] M) (Φ : X → ∀ j, _) := ∀ a :
    ∀ j, K j, (∀ j ≥ m, a j = 1) → ∀ β : _ →ₗ[ℂ] _, ∑ x ∈ s, L x (β (TensorChain.pure (fun j ↦
  (k j).ω (a j, a (j + 1)) (Φ x j)) m)) = ∑ x ∈ s, L x (β (TensorChain.pure (Φ x) m))
